Các trường siêu dữ liệu (metadata) được lưu trữ cho mỗi lệnh.
các thông tin metadata lưu kèm bản ghi
danh sách trường dữ liệu lưu cho mỗi bản ghi
siêu dữ liệu lưu trữ gồm những gì', '65a5f9c2a54fe3d65c4beb6a9c895e41a9395cc378f3b358376b62c1cc41c3b2');
INSERT INTO entries (sheet_id, card_pos, section_pos, position, card, section, kind, command, description, details, example, danger, lang, display, embed_text, content_hash, description_vi, embed_text_vi, content_hash_vi) VALUES (1, 8, 1, 1, 'Example config.toml', NULL, 'snippet', '## ~/.config/atuin/config.toml

# Sync
auto_sync        = true
sync_frequency  = "5m"
sync_address    = "https://api.atuin.sh"

# UI
theme           = "default"
keymap_mode     = "vim-insert"
filter_mode     = "global"
search_mode     = "fuzzy"

# Columns shown in search TUI
columns = ["time", "duration", "exit_code", "command"]

# Exclude commands from history
history_filter = [
  "^sudo -i$",
  "^ .*",        # leading space = private
]

# Exclude directories from recording
cwd_filter = [
  "/tmp/.*",
  "/private/.*",
]

# Updates
check_update             = true
update_check_interval   = "1d"', NULL, NULL, NULL, NULL, 'toml', '{"raw": "## ~/.config/atuin/config.toml\n\n# Sync\nauto_sync        = true\nsync_frequency  = \"5m\"\nsync_address    = \"https://api.atuin.sh\"\n\n# UI\ntheme           = \"default\"\nkeymap_mode     = \"vim-insert\"\nfilter_mode     = \"global\"\nsearch_mode     = \"fuzzy\"\n\n# Columns shown in search TUI\ncolumns = [\"time\", \"duration\", \"exit_code\", \"command\"]\n\n# Exclude commands from history\nhistory_filter = [\n  \"^sudo -i$\",\n  \"^ .*\",        # leading space = private\n]\n\n# Exclude directories from recording\ncwd_filter = [\n  \"/tmp/.*\",\n  \"/private/.*\",\n]\n\n# Updates\ncheck_update             = true\nupdate_check_interval   = \"1d\""}'::jsonb, 'Atuin › Example config.toml
## ~/.config/atuin/config.toml

# Sync
auto_sync        = true
sync_frequency  = "5m"
sync_address    = "https://api.atuin.sh"

# UI
theme           = "default"
keymap_mode     = "vim-insert"
filter_mode     = "global"
search_mode     = "fuzzy"

# Columns shown in search TUI
columns = ["time", "duration", "exit_code", "command"]

# Exclude commands from history
history_filter = [
  "^sudo -i$",
  "^ .*",        # leading space = private
]

# Exclude directories from recording
cwd_filter = [
  "/tmp/.*",
  "/private/.*",
]

# Updates
check_update             = true
update_check_interval   = "1d"', '6fae44a4fcd7f6444bd886773fa3ec388070fb2bdcc6c8ff73993cff77337d21', 'File cấu hình mẫu config.toml cho đồng bộ, giao diện và bộ lọc lịch sử shell', 'Atuin › Example config.toml
## ~/.config/atuin/config.toml

# Sync
auto_sync        = true
sync_frequency  = "5m"
sync_address    = "https://api.atuin.sh"

# UI
theme           = "default"
keymap_mode     = "vim-insert"
filter_mode     = "global"
search_mode     = "fuzzy"

# Columns shown in search TUI
columns = ["time", "duration", "exit_code", "command"]

# Exclude commands from history
history_filter = [
  "^sudo -i$",
  "^ .*",        # leading space = private
]

# Exclude directories from recording
cwd_filter = [
  "/tmp/.*",
  "/private/.*",
]

# Updates
check_update             = true
update_check_interval   = "1d"
File cấu hình mẫu config.toml cho đồng bộ, giao diện và bộ lọc lịch sử shell
file config mẫu toml đồng bộ lịch sử terminal
cấu hình giao diện và phím tắt tìm kiếm history shell
thiết lập tự động sync và lọc lịch sử dòng lệnh', '36d0016bc9728720fbaac220871e6d484b5e03e88d66baa50d8aac4be51a20d8');

