-- neovim
INSERT INTO sheets (id, slug, title, subtitle, badge, description, logo, source_url, links, meta, aliases, layout) VALUES (3, 'neovim', 'Neovim Cheatsheet', 'Complete nvim command reference - searchable, fast, always free', NULL, 'A fast, searchable Neovim cheatsheet covering every essential nvim command: modes, navigation, editing, text objects, search & replace, splits, tabs, buffers, macros, LSP, and more.', NULL, 'https://neovimcheatsheet.com/', '[{"label": "neovim.io", "url": "https://neovim.io"}]'::jsonb, '{"legend": [{"badge": "N", "badge_class": "badge-n", "label": "Normal", "tip": "The default mode - you''re here unless you''ve switched. Navigate, run operators, and issue commands. Enter with Esc from any other mode. Most commands only work in Normal mode."}, {"badge": "I", "badge_class": "badge-i", "label": "Insert", "tip": "Type text directly into the buffer. Enter with i (before cursor), a (after), o (new line below), or O (new line above). Return to Normal with Esc or Ctrl+[."}, {"badge": "V", "badge_class": "badge-v", "label": "Visual", "tip": "Select text interactively, then apply an operator. Enter with v (character), V (line), or Ctrl+v (block). Apply d, c, y, >, < to the selection - returns to Normal automatically."}, {"badge": "C", "badge_class": "badge-c", "label": "Command", "tip": "Type Ex commands starting with :, or search with / and ?. Enter with : from Normal mode. Run with Enter, cancel with Esc. Supports tab completion for commands, files, and options."}]}'::jsonb, ARRAY['neovim', 'nvim', 'vim']::text[], '[{"title": "Modes", "color": "green", "tip": "Neovim has distinct modes for different tasks. Normal is default - navigate and issue commands. Switch with i/a/o (Insert), v/V/Ctrl+v (Visual), or : (Command). Always return to Normal with Esc.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Navigation - Basic", "tip": "In Normal mode use h/j/k/l instead of arrow keys. Combine motions with counts: 5j moves 5 lines down. Motions also work as operator arguments - d5j deletes 5 lines down.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Editing", "color": "orange", "tip": "Operators like d (delete), c (change), and y (yank) act on motions or text objects. Most edits go into the unnamed register and can be pasted with p. Use . to repeat the last change.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Text Objects (combine with d/c/y/v)", "color": "purple", "tip": "Text objects describe a region by structure: words, sentences, paragraphs, or delimiters. Combine with any operator: operator + i/a + object. Example: diw deletes inner word, ci( changes inside parens.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Search & Replace", "color": "red", "tip": "Search with /pattern (forward) or ?pattern (backward). Press n/N to cycle matches. :%s/old/new/g replaces all occurrences in the file - add c flag to confirm each match individually.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Splits & Windows", "color": "yellow", "tip": "Display multiple buffers side by side in split windows. Use :sp for horizontal and :vsp for vertical splits. Navigate splits with Ctrl+w + h/j/k/l. Resize with Ctrl+w +/-/_/|.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Tabs", "color": "teal", "tip": "Tabs in Neovim are tab pages - each holds its own window layout, not just a single file. Use :tabnew to open a tab, gt/gT to switch. A single tab can contain multiple splits.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Files & Buffers", "tip": "A buffer is an in-memory copy of a file. You can have many buffers open at once - :ls lists them all, :bn/:bp navigates between them. Splits and tabs are just different views into buffers.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Marks & Jumps", "color": "purple", "tip": "Marks bookmark positions in a file. Lowercase marks (m{a-z}) are local to the buffer; uppercase (m{A-Z}) are global across files. The jump list (Ctrl+o/Ctrl+i) tracks everywhere you''ve jumped.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Macros", "color": "orange", "tip": "Macros record a sequence of keystrokes into a named register. Press q{letter} to start recording, make your edits, then q to stop. Replay with @{letter} or run N times with {N}@{letter}.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Visual Mode", "color": "green", "tip": "Select text interactively before applying an operator. Enter with v (character), V (line), or Ctrl+v (block). Apply d, c, y, >, < to the selection - Neovim returns to Normal automatically.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Folding", "color": "red", "tip": "Collapse sections of a file to reduce visual noise. Requires a foldmethod (manual, indent, expr, marker, syntax, or diff). Use zc/zo to close/open a fold, zM/zR to close/open all folds in the file.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Neovim-Specific", "color": "teal", "tip": "Features unique to Neovim or its ecosystem. LSP keymaps (grr, gri, grn, gra, etc.) are built-in defaults, no config needed, working on any machine or server (K hover and ]d/[d diagnostics since 0.10; the gr* family since 0.11). Note: gd is a built-in Vim motion (local declaration), not an LSP default. Plugin managers like Lazy.nvim and Mason require installation.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}, {"title": "Useful Commands", "tip": "Handy Ex commands for customizing your editing environment on the fly. Make any :set option permanent by adding it to your init.lua (or init.vim) config file so it''s applied on every launch.", "layout": "grid", "body_cols": 1, "sections": [{"kind": "table", "copy_lines": false}]}]'::jsonb);
